import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, positionLocal, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DirectionalLight } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findText = (role, fallback) => {
    const it = items.find((i) => i.role === role);
    return (it?.text ?? fallback);
  };

  const captionText = findText('caption', 'NOVA ATELIER / CALIBRE PROGRAM');
  const heroText = findText('hero', 'TIME, MACHINED.');
  const subheadText = findText('subhead', 'Every calibre begins as a solid billet.');

  const group = new Group();
  group.name = 'kinetic-headline';

  const timelines = [];
  const disposables = [];
  const primitiveHandles = [];

  // ---- Backdrop: 7 x 5.5 vertical gradient plane at z=-1.5 ----
  const bgGeo = new PlaneGeometry(7, 5.5);
  const bgMat = new MeshBasicNodeMaterial();
  const c0 = new Color(colors.gradientStops?.[0]?.hex ?? colors.background ?? '#0b0b10');
  const c1 = new Color(colors.gradientStops?.[1]?.hex ?? '#13131a');
  const grad = mix(
    vec3(c0.r, c0.g, c0.b),
    vec3(c1.r, c1.g, c1.b),
    uv().y
  );
  bgMat.colorNode = grad;
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -1.5);
  group.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // ---- Node-local rim/accent light ----
  const rim = new DirectionalLight(new Color(colors.accent ?? '#ff2a38'), 0.8);
  rim.position.set(-3, 2, 2);
  group.add(rim);
  const key = new DirectionalLight(new Color('#e8ecf2'), 1.0);
  key.position.set(3, 3, 4);
  group.add(key);

  // ---- Caption kicker (y = 1.15) ----
  const caption = ctx.fontAtlas.createText(captionText.toUpperCase(), {
    fontSize: 18,
    color: colors.paper ?? '#e8ecf2',
    align: 'center',
    letterSpacingPx: 3,
  });
  caption.position.set(0, 1.15, 0.05);
  caption.scale.setScalar(0.9);
  group.add(caption);

  // ---- Hero headline (dimensional type) ----
  // Build per-word groups for z parallax; kinetic entrance simulated per-word.
  const heroWords = heroText.split(' ');
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  group.add(heroGroup);

  const wordObjs = [];
  // z offsets front-to-back: 0.12 / 0.0 / -0.12
  const zOffsets = [0.12, 0.0, -0.12];

  // Layout words horizontally. Approximate width per char.
  const heroFontSize = 124;
  const emScale = 0.62 / (heroFontSize); // scene units per px roughly for em height
  let cursorX = 0;
  const wordMeta = [];
  heroWords.forEach((w, i) => {
    const wo = ctx.fontAtlas.createText(w, {
      fontSize: heroFontSize,
      color: colors.paper ?? '#e8ecf2',
      align: 'left',
    });
    const zo = zOffsets[i % zOffsets.length];
    wo.position.set(cursorX, 0, zo);
    // approximate advance width
    const approxW = w.length * heroFontSize * emScale * 0.62;
    cursorX += approxW + heroFontSize * emScale * 0.4;
    wordMeta.push({ obj: wo, approxW });
    heroGroup.add(wo);
    wordObjs.push(wo);
  });

  // center the hero group
  const totalW = cursorX - heroFontSize * emScale * 0.4;
  heroGroup.children.forEach((ch) => {
    if (ch.isMesh || ch.isGroup) ch.position.x -= totalW / 2;
  });

  // ---- Accent underline rule ----
  const ulGeo = new PlaneGeometry(2.6, 0.045);
  const ulMat = new MeshStandardNodeMaterial();
  const accentColor = new Color(colors.accent ?? '#ff2a38');
  ulMat.color = accentColor;
  ulMat.emissive = accentColor;
  ulMat.emissiveIntensity = 1.2;
  ulMat.roughness = 0.6;
  ulMat.metalness = 0.2;
  const underline = new Mesh(ulGeo, ulMat);
  underline.position.set(0, -0.05, 0.02);
  underline.scale.x = 0;
  group.add(underline);
  disposables.push(ulGeo, ulMat);

  // ---- Subhead (y = -0.65) ----
  const subhead = ctx.fontAtlas.createText(subheadText, {
    fontSize: 40,
    color: colors.paper ?? '#e8ecf2',
    align: 'center',
  });
  subhead.position.set(0, -0.65, 0.05);
  group.add(subhead);

  // ================= MOTION =================
  const ease = 'power3.out';

  // caption fade
  caption.traverse((o) => { if (o.material) o.material.transparent = true; });
  const capTl = gsap.timeline();
  caption.position.y = 1.35;
  capTl.fromTo(caption.position, { y: 1.35 }, { y: 1.15, duration: 0.5, ease: 'power2.out' });
  timelines.push(capTl);

  // Hero per-word rise + settle
  const heroTl = gsap.timeline();
  wordObjs.forEach((wo, i) => {
    wo.position.y += 0.35;
    wo.traverse((o) => { if (o.material) { o.material.transparent = true; o.material.opacity = 0; } });
    const baseY = wo.position.y - 0.35;
    heroTl.to(wo.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, i * 0.06);
    wo.traverse((o) => {
      if (o.material) {
        heroTl.to(o.material, { opacity: 1, duration: 0.7, ease: 'power2.out' }, i * 0.06);
      }
    });
  });

  // weighted settle on the last word landing
  const lastStart = (wordObjs.length - 1) * 0.06;
  heroGroup.scale.setScalar(1.04);
  heroTl.to(heroGroup.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9, ease: 'power4.out',
  }, lastStart + 0.7);

  // underline scaleX anchored left, starting 120ms after last glyph
  underline.position.x = -1.3;
  const ulTl = gsap.timeline();
  ulTl.to(underline.scale, {
    x: 1, duration: 0.5, ease: 'power2.out',
    onUpdate: () => { underline.position.x = -1.3 + underline.scale.x * 1.3; },
  }, lastStart + 0.7 + 0.12);
  timelines.push(ulTl);
  timelines.push(heroTl);

  // subhead fade up
  subhead.traverse((o) => { if (o.material) { o.material.transparent = true; o.material.opacity = 0; } });
  subhead.position.y = -0.85;
  const subTl = gsap.timeline({ delay: lastStart + 0.5 });
  subTl.to(subhead.position, { y: -0.65, duration: 0.5, ease: 'power2.out' }, 0);
  subhead.traverse((o) => {
    if (o.material) subTl.to(o.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  });
  timelines.push(subTl);

  // ---- Apply cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      try {
        const handle = fn(heroGroup, p.params ?? {});
        if (handle) primitiveHandles.push(handle);
      } catch (e) { /* primitive optional */ }
    }
  }

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primitiveHandles.forEach((h) => { try { h.cleanup && h.cleanup(); } catch (e) {} });
    disposables.forEach((d) => { try { d.dispose && d.dispose(); } catch (e) {} });
  };

  return group;
}
